#!/usr/bin/env bash
# Syncs the chart with an AIsolate release: appVersion and the CRDs of the release's tag (chart/crds, generated by
# the controller, never edited by hand). The images are the fleet's deploy/release flow's: aisolate/aisolate's
# release-deploy keeps chart/values.yaml on main's internal tags, chart-prepare-release promotes them to
# docker-public and bumps the chart's version. Run this on that release branch.
# Usage: scripts/sync-app.sh <appVersion> [--dry-run]   (bash 3.2, yq; git and tar for the CRDs)
set -euo pipefail
cd "$(dirname "$0")/.."

app_repo=git@ssh.gitlab.reportix.com:aisolate/aisolate.git

if [[ $# == 1 || ( $# == 2 && $2 == --dry-run ) ]]; then mode=${2:-sync} version=$1; else mode= version=; fi
[[ $mode && $version =~ ^[A-Za-z0-9_][A-Za-z0-9_.-]*$ ]] || { echo "usage: $0 <appVersion> [--dry-run]" >&2; exit 2; }

git ls-remote --exit-code --tags "$app_repo" "refs/tags/$version" >/dev/null 2>&1 \
  || { echo "FAIL: $app_repo has no tag $version" >&2; exit 1; }
if [[ $mode == --dry-run ]]; then
  echo "would write appVersion \"$version\" to chart/Chart.yaml and replace chart/crds/*.yaml with crds/*.yaml of $app_repo at $version"
  exit 0
fi

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
git archive --remote="$app_repo" "$version" crds | tar -x -C "$tmp"
crds=("$tmp"/crds/*.yaml)
[[ -e ${crds[0]} ]] || { echo "FAIL: $app_repo has no crds/*.yaml at $version" >&2; exit 1; }

# sed, not yq -i: yq unfolds Chart.yaml's description.
sed "s/^appVersion: .*/appVersion: \"$version\"/" chart/Chart.yaml > "$tmp/Chart.yaml"
[[ $(yq '.appVersion' "$tmp/Chart.yaml") == "$version" ]] || { echo "FAIL: chart/Chart.yaml has no appVersion line" >&2; exit 1; }

mv "$tmp/Chart.yaml" chart/Chart.yaml
rm -f chart/crds/*.yaml
mv "${crds[@]}" chart/crds/
echo "synced appVersion $version and ${#crds[@]} CRDs; next: tests/chart/regenerate.sh, then the release MR"
